    "whoItServes": "သက်ကြီးရွယ်အိုတွေ၊ အိုးမဲ့အိမ်မဲ့အိမ်နီးချင်းတွေ၊ အဲကွန်း ဒါမှမဟုတ် အပူပေးစက် မကောင်းသူတွေ၊ ပြင်ပအလုပ်သမားတွေနဲ့ နေအိမ်က ရာသီဥတုကို မနိုင်တဲ့သူတိုင်း။",
