    "whatYoullNeed": "ကူညီမယ့်လက်တွေ၊ အသက်အရွယ်နဲ့ အရွယ်အစားစုံ ပေးထားတဲ့ပစ္စည်းတွေ၊ ခေတ္တနားခွင့်ကူညီသူတွေ၊ အေဂျင်စီတွေနဲ့ ကျောင်းတွေနဲ့ မိတ်ဖက်ဆက်ဆံရေးပါ။ စောင့်ရှောက်ခံကလေးတွေနဲ့ဆိုင်တဲ့အလုပ်က သိမ်မွေ့ပြီး ဥပဒေနဲ့အုပ်မိုးထားတာပါ — ကလေးတွေနဲ့အလုပ်လုပ်မယ့်သူတိုင်း စုံစမ်းစစ်ကြည့်ပါ၊ မဖြစ်မနေအကြောင်းကြားရမှုနဲ့ လျှို့ဝှက်မှုစည်းမျဉ်းတွေကို တစ်လုံးမကျန် လိုက်နာပါ၊ သက်ဆိုင်ရာအေဂျင်စီတွေကို ရှောင်ကွင်းမလုပ်ဘဲ သူတို့နဲ့ တွဲညှိပါ။",
    "setupHours": 24,
    "defaultCategory": "childcare",
    "firstSteps": "ဒေသက မွေးစားရေးအေဂျင်စီ ဒါမှမဟုတ် ဆွေမျိုးပြုစုသူလမ်းညွှန်အစီအစဉ်နဲ့ ထိုင်ဆွေးနွေးတာနဲ့ စပါ — ကူညီသူတစ်ဦးမှ မရှာခင် ဒီအလုပ်ကို အုပ်မိုးတဲ့စည်းမျဉ်းတွေ (စုံစမ်းစစ်ကြည့်မှု၊ မဖြစ်မနေအကြောင်းကြားရမှု၊ လျှို့ဝှက်မှု) ကို လေ့လာပြီး ကွက်လပ်တွေ တကယ်ဘယ်မှာရှိလဲ သူတို့ဆီက နားထောင်ပါ။ ပြီးရင် ပြုစုနေတဲ့မိသားစုအချို့ကို ပထမအပတ်နဲ့ ပထမနှစ်မှာ ဘာလိုခဲ့လဲ မေးပါ — ဘယ်သူမှမတောင်းတဲ့ ပစ္စည်းဂိုဒေါင်ဆီမဟုတ်ဘဲ အဲဒီအဖြေတွေဆီ တည်ဆောက်ပါ။",
